#include <vector>
#include <iostream>
#include <type_traits>

int main() {
    using IntVec = std::vector<int>;

    // 1. Check the type
    using AllocType = IntVec::allocator_type;
    static_assert(std::is_same_v<AllocType, std::allocator<int>>);

    IntVec v;

    // 2. Retrieve the instance
    AllocType alloc_instance = v.get_allocator();

    // Note: For std::allocator, the instance is stateless and trivial.
    // For custom allocators, this instance holds the required state.
    std::cout << "Allocator type retrieved successfully.";
}
